function generateBlog(slug) {
  const config = BLOG_CONFIG[slug];
  if (!config) return;

  // Breadcrumb Schema
  const breadcrumbSchema = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    "itemListElement": [
      { "@type": "ListItem", "position": 1, "name": "Home", "item": "https://nexkittool.com/" },
      { "@type": "ListItem", "position": 2, "name": "Blog", "item": "https://nexkittool.com/blog/" },
      { "@type": "ListItem", "position": 3, "name": config.title, "item": `https://nexkittool.com/blog/${slug}.html` }
    ]
  };

  // Article Schema
  const articleSchema = {
    "@context": "https://schema.org",
    "@type": "Article",
    "headline": config.title,
    "description": config.metaDesc,
    "author": { "@type": "Person", "name": "Sumit Tiwari", "jobTitle": "Founder & Developer", "url": "https://nexkittool.com/pages/about.html" },
    "publisher": { "@type": "Organization", "name": "Nexkittool", "url": "https://nexkittool.com" },
    "datePublished": "2026-07-12",
    "dateModified": "2026-07-12",
    "mainEntityOfPage": `https://nexkittool.com/blog/${slug}.html`
  };

  // FAQ Schema
  const faqSchema = {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": config.faqs.map(faq => ({
      "@type": "Question",
      "name": faq.q,
      "acceptedAnswer": { "@type": "Answer", "text": faq.a }
    }))
  };

  const schemasHtml = `
<script type="application/ld+json">${JSON.stringify(breadcrumbSchema)}</script>
<script type="application/ld+json">${JSON.stringify(articleSchema)}</script>
<script type="application/ld+json">${JSON.stringify(faqSchema)}</script>
  `.trim();

  // Body sections
  const bodyHtml = config.sections.map(sec => `
    <h2>${sec.h2}</h2>
    <p>${sec.text}</p>
  `.trim()).join('\n\n  ');

  // FAQ Accordion
  const faqHtml = config.faqs.map(faq => `
    <details class="faq-item">
      <summary>${faq.q}</summary>
      <div><p>${faq.a}</p></div>
    </details>
  `.trim()).join('\n  ');

  let categorySubIntro = '';
  let categoryWorkflows = '';

  if (config.category === 'pdf' || config.category === 'image') {
    categorySubIntro = `<p>To succeed in managing digital documents, efficiency is everything. In this guide, we dive deep into how to perform this workflow seamlessly, outlining best practices, secure tools, and advanced settings that will save you time and preserve layout structure.</p>`;
    categoryWorkflows = `<h2>Advanced Document Workflows & Best Practices</h2>
  <p>When working with files online, following a structured workflow is recommended:</p>
  <ul>
    <li><strong>Keep backups:</strong> Always keep a copy of your original files before executing compression or formatting changes.</li>
    <li><strong>Review document alignment:</strong> Check page sequences and headings after performing conversions to verify layout accuracy.</li>
    <li><strong>Check font packages:</strong> Verify standard fonts are used in documents to ensure correct rendering.</li>
  </ul>`;
  } else if (config.category === 'ai') {
    categorySubIntro = `<p>To succeed in professional AI writing, striking the right balance between automation and human insight is everything. In this guide, we dive deep into how to leverage AI tools seamlessly, outlining best practices, editing strategies, and writing settings that will save you time and elevate your copy quality.</p>`;
    categoryWorkflows = `<h2>Advanced AI Writing Workflows & Best Practices</h2>
  <p>When generating content utilizing AI writing engines, following a structured workflow is recommended:</p>
  <ul>
    <li><strong>Outline your research:</strong> Always draft a structural outline containing your main arguments before utilizing generators.</li>
    <li><strong>Fact-check data:</strong> Manually verify any statistics, references, or historical dates generated by the AI model.</li>
    <li><strong>Humanize the voice:</strong> Edit the vocabulary, intro, and conclusion paragraphs to match your personal brand voice.</li>
  </ul>`;
  } else {
    categorySubIntro = `<p>To succeed in managing digital workflows, efficiency is everything. In this guide, we dive deep into how to leverage digital tools seamlessly, outlining best practices, configuration options, and settings that will save you time and improve your productivity.</p>`;
    categoryWorkflows = `<h2>Advanced Digital Workflows & Best Practices</h2>
  <p>When using web utility tools online, following a structured workflow is recommended:</p>
  <ul>
    <li><strong>Keep backups:</strong> Always keep a copy of your original files or data parameters before generating new configurations.</li>
    <li><strong>Verify scannability and outputs:</strong> Check generated layouts, parameters, and sizes on different devices to ensure usability.</li>
    <li><strong>Secure configuration keys:</strong> Avoid exposing sensitive data keys or passwords inside shared setups.</li>
  </ul>`;
  }

  // Generate related articles dynamically
  const allSlugs = Object.keys(BLOG_CONFIG);
  const otherSlugs = allSlugs.filter(s => s !== slug);
  const sortedSlugs = otherSlugs.sort((a, b) => {
    const catA = BLOG_CONFIG[a].category === config.category ? 1 : 0;
    const catB = BLOG_CONFIG[b].category === config.category ? 1 : 0;
    return catB - catA;
  });
  const relatedSlugs = sortedSlugs.slice(0, 4);
  const relatedHtml = relatedSlugs.map(s => {
    const relConfig = BLOG_CONFIG[s];
    let emoji = '📝';
    if (relConfig.category === 'pdf') emoji = '📄';
    else if (relConfig.category === 'image') emoji = '🖼️';
    else if (relConfig.category === 'ai') emoji = '🤖';
    else if (relConfig.category === 'utility') emoji = '🛠️';
    
    let cardTitle = relConfig.title;
    if (cardTitle.length > 45) {
      cardTitle = cardTitle.substring(0, 42) + '...';
    }
    return `<div class="related-card"><h4>${emoji} ${cardTitle}</h4><a href="/blog/${s}.html">Read Guide →</a></div>`;
  }).join('\n    ');

  let pageContent = MASTER_BLOG_TEMPLATE
    .replace(/{{TITLE}}/g, config.title)
    .replace(/{{METADESC}}/g, config.metaDesc)
    .replace(/{{SLUG}}/g, slug)
    .replace(/{{BADGE}}/g, config.badge)
    .replace(/{{READ_TIME}}/g, config.readTime)
    .replace(/{{INTRO}}/g, config.intro)
    .replace(/{{CATEGORY_SUB_INTRO}}/g, categorySubIntro)
    .replace(/{{CATEGORY_WORKFLOWS}}/g, categoryWorkflows)
    .replace(/{{BODY_SECTIONS}}/g, bodyHtml)
    .replace(/{{FAQ_ACCORDION}}/g, faqHtml)
    .replace(/{{SCHEMAS}}/g, schemasHtml)
    .replace(/{{RELATED_ARTICLES}}/g, relatedHtml);

  // Write out file
  const outFile = path.join(__dirname, 'blog', `${slug}.html`);
  fs.writeFileSync(outFile, pageContent, 'utf-8');
  console.log(`Generated blog post: ${outFile}`);
}

